   var addressCard=new Surface(){Tone=PaletteTone.Blue,Margin=new Padding(0,0,0,12)};Add(stack,addressCard,136);var name=Label("Адрес для устройств",12);name.Location=new Point(22,16);addressCard.Controls.Add(name);
   lanAddressBox=new NoWheelComboBox(){DropDownStyle=ComboBoxStyle.DropDownList,Location=new Point(24,45),Width=520,Font=Theme.Font(9)};addressCard.Controls.Add(Theme.Input(lanAddressBox,32));lanAddressBox.SelectedIndexChanged+=delegate{UpdateNetworkStatus();};
