  void RefreshAddresses(){if(lanAddressBox==null||lanAddressBox.IsDisposed)return;string old=CurrentLanIP();lanAddressBox.Items.Clear();try{foreach(var item in NetworkInfo.Addresses())lanAddressBox.Items.Add(item);}catch(Exception ex){AddLog("Не удалось получить адреса сетевых адаптеров: "+ex.Message);}if(lanAddressBox.Items.Count>0){int index=0;for(int i=0;i<lanAddressBox.Items.Count;i++)if(((LanAddress)lanAddressBox.Items[i]).Address==old)index=i;lanAddressBox.SelectedIndex=index;}UpdateNetworkStatus();}
  string CurrentLanIP(){var address=lanAddressBox==null||lanAddressBox.IsDisposed?null:lanAddressBox.SelectedItem as LanAddress;return address==null?"":address.Address;}
  void UpdateNetworkStatus(){if(networkStatus==null||networkStatus.IsDisposed)return;string ip=CurrentLanIP();networkStatus.Text=ip==""?"Частный IPv4-адрес не найден, сначала подключитесь к Wi-Fi / проводной сети.":ip+":"+store.State.Port+"  ·  "+(store.State.AllowLan?(engine.Running?"Доступ работает":"Настроено, нужно запустить ядро"):"Доступ выключен")+"  ·  "+(store.State.LanAuthentication?"Нужна авторизация":"Без авторизации");}
  void SaveLan(){try{bool enabled=lanEnabled.Checked,auth=lanAuth.Checked;string user=lanUser.Text.Trim(),password=lanPassword.Text;Config.ValidateLan(enabled,auth,user,password);bool changed=enabled!=store.State.AllowLan||auth!=store.State.LanAuthentication||user!=store.State.LanUser||password!=store.State.LanPassword;if(engine.Running&&changed)throw new InvalidOperationException("Сначала остановите ядро на странице «Обзор», затем сохраните настройки LAN и запустите ядро снова.");bool oldEnabled=store.State.AllowLan,oldAuth=store.State.LanAuthentication;string oldUser=store.State.LanUser,oldPassword=store.State.LanPassword;store.State.AllowLan=enabled;store.State.LanAuthentication=auth;store.State.LanUser=user;store.State.LanPassword=password;try{store.Save();}catch{store.State.AllowLan=oldEnabled;store.State.LanAuthentication=oldAuth;store.State.LanUser=oldUser;store.State.LanPassword=oldPassword;throw;}UpdateNetworkStatus();AddLog("Настройки доступа из локальной сети сохранены."+(enabled?"Вступит в силу после запуска ядра.":"Общий доступ выключен."));Feedback("Настройки доступа сохранены.");}catch(Exception ex){Error(ex);}}
  void CopyLanAddress(){try{string ip=CurrentLanIP();if(ip=="")throw new InvalidOperationException("Сначала подключитесь к локальной сети и обновите адреса.");Clipboard.SetText(ip+":"+store.State.Port);Feedback("Адрес прокси скопирован.");}catch(Exception ex){Error(ex);}}
  void ShowLanHelp(){string ip=CurrentLanIP();if(ip=="")ip="IPv4-адрес этого компьютера в LAN";using(var dialog=new Form(){Text="Инструкция для локальной сети",ClientSize=new Size(660,510),StartPosition=FormStartPosition.CenterParent,Font=Theme.Font(9),MinimizeBox=false,MaximizeBox=false}){
   var text=new TextBox(){Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill,BorderStyle=BorderStyle.None,Text=NetworkInfo.Instructions(ip,store.State,engine.Running)};var buttons=Row();buttons.Dock=DockStyle.Bottom;buttons.Padding=new Padding(16,5,0,0);buttons.Controls.Add(Button("Копировать",delegate{try{Clipboard.SetText(text.Text);}catch(Exception ex){MessageBox.Show(dialog,ex.Message);}},true,116));var close=new SoftButton(){Text="Закрыть",DialogResult=DialogResult.Cancel};buttons.Controls.Add(close);dialog.Controls.Add(text);dialog.Controls.Add(buttons);dialog.Padding=new Padding(22);dialog.CancelButton=close;Theme.Apply(dialog);dialog.ShowDialog(this);
  }}
  void ConnectionsPage(){var stack=Stack();content.Controls.Add(stack);var row=Row();row.Controls.Add(Button("Обновить",RefreshConnections,false,116));connectionCount=Label("Обновление каждые 2 с · активных соединений: 0",9,true);connectionCount.Margin=new Padding(10,10,0,0);row.Controls.Add(connectionCount);Add(stack,row,58);
   var card=new Surface(){Padding=new Padding(14),Margin=new Padding(0,0,0,14)};connections=List("Назначение","Устройство","Протокол","Правило","Трафик");connections.Columns[0].Width=245;connections.Columns[1].Width=155;connections.Columns[2].Width=110;connections.Columns[3].Width=120;connections.Dock=DockStyle.Fill;card.Controls.Add(connections);Add(stack,card,-1);
   var actions=Row();actions.Controls.Add(AvailableButton("Отключить",CloseSelectedConnection,delegate{return engine.Running&&connections.SelectedItems.Count>0;},false,116));actions.Controls.Add(AvailableButton("Откл. все",CloseAllConnections,delegate{return engine.Running&&connections.Items.Count>0;},false,116));connections.SelectedIndexChanged+=delegate{RefreshActions();};Add(stack,actions,52);Add(stack,Label("Отключение закрывает текущие соединения, приложения могут переподключиться.",8,true),34);
