  void FillConnections(Dictionary<string,object> data){if(connections==null||connections.IsDisposed)return;var rows=ConnectionInfo.Parse(data);var ids=new HashSet<string>(rows.Select(x=>x.Id));var existing=connections.Items.Cast<ListViewItem>().ToDictionary(x=>x.Tag as string);var top=connections.Items.Count>0?connections.TopItem:null;connections.BeginUpdate();try{foreach(var item in existing.Values)if(!ids.Contains(item.Tag as string))connections.Items.Remove(item);foreach(var info in rows){string[] values={info.Target,info.Source,info.Protocol,info.Rule,Engine.Bytes(info.Upload)+" / "+Engine.Bytes(info.Download)};ListViewItem item;if(!existing.TryGetValue(info.Id,out item)){connections.Items.Add(new ListViewItem(values){Tag=info.Id});}else for(int i=0;i<values.Length;i++)if(item.SubItems[i].Text!=values[i])item.SubItems[i].Text=values[i];}}finally{connections.EndUpdate();}if(top!=null&&top.ListView==connections)connections.TopItem=top;if(connectionCount!=null&&!connectionCount.IsDisposed)connectionCount.Text="Обновление каждые 2 с · активных соединений: "+rows.Count;RefreshActions();}
  void RefreshConnections(){if(!engine.Running){FillConnections(new Dictionary<string,object>());Feedback("Запустите ядро, чтобы увидеть соединения.");return;}int generation=engine.Generation;Dictionary<string,object> data=null;Run(delegate{data=engine.Api("GET","/connections",null);},delegate{if(generation==engine.Generation)FillConnections(data);},"Обновление соединений…");}
  void CloseSelectedConnection(){try{if(!engine.Running)throw new InvalidOperationException("Сначала запустите ядро.");if(connections==null||connections.SelectedItems.Count==0)throw new InvalidOperationException("Сначала выберите соединение.");string id=connections.SelectedItems[0].Tag as string;Run(delegate{engine.Api("DELETE","/connections/"+Uri.EscapeDataString(id),null);},RefreshConnections);}catch(Exception ex){Error(ex);}}
  void CloseAllConnections(){if(!engine.Running)return;if(MessageBox.Show(this,"Разорвать все текущие соединения через прокси? Приложения могут переподключиться.","Отключить",MessageBoxButtons.YesNo,MessageBoxIcon.Question,MessageBoxDefaultButton.Button2)!=DialogResult.Yes)return;Run(delegate{engine.Api("DELETE","/connections",null);},RefreshConnections);}
 }
